(()=>{
 'use strict';
 const records=window.portfolioCollection,stage=document.querySelector('#story-stage');
 const record=id=>records.find(r=>r.id===id);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const photo=(id,n=0)=>record(id)?.images?.[n]?.src;
 const image=(src,alt,cls='')=>`<img class="${cls}" data-src="${esc(src)}" alt="${esc(alt)}" loading="lazy" decoding="async">`;
 const detail=(id,label='Inside the project')=>`<button class="story-link" type="button" data-project="${id}">${label} <span aria-hidden="true">↗</span></button>`;
 const film=(id,label)=>`<button class="film-window layer" data-direction="right" data-project="${id}" type="button" aria-label="Watch ${esc(label)}">${image(photo(id),label)}<span class="film-play"><span aria-hidden="true">▶</span> Watch ${label}</span></button>`;
 const copy=(label,title,body,links='')=>`<div class="chapter-copy layer" data-direction="left"><p class="eyebrow">${label}</p><h2>${title}</h2><p class="chapter-description">${body}</p><div class="chapter-links">${links}</div></div>`;
 const chapters=[
 {id:'work',name:'What comes next?',theme:'light',kind:'invitation',html:`<div class="invitation-copy layer" data-direction="bottom"><p class="eyebrow">Pioneering new ways to learn, connect and create</p><h2>What could we<br><em>build together?</em></h2><p>A new product. A live experience. A team ready to do something it hasn’t done before.</p><div class="invitation-actions"><a class="primary-action" href="https://calendar.app.google/pZkjBD1BnG83RQxi7" data-booking>Let’s arrange a call</a><a class="story-link" href="#origins">Follow the story ↓</a><button class="story-link" data-library>Explore all the work</button></div></div><div class="invitation-reel layer" data-direction="right">${['good-omen','rory','creative-community'].map(id=>`<button data-project="${id}" aria-label="Explore ${esc(record(id).title)}">${image(photo(id),record(id).title)}</button>`).join('')}</div><p class="chapter-tail">Scroll to see how one breakthrough leads to the next.</p>`},
 {id:'origins',name:'A different kind of business',theme:'light',html:copy('The beginning / Fikay','It started with<br>a different way<br>to do business.','At nineteen, I wanted to build a business that created opportunity. Fikay connected ethical fashion, livelihoods and education. It taught me that a new idea matters when you bring people into it.',detail('fikay','The Fikay story'))+`<div class="evidence-composition layer" data-direction="right">${image('assets/optimised/fikay-cambodia.webp','A Cambodian artisan pictured in the 2015 Fikay feature','portrait-evidence')}<p class="evidence-credit">The people behind the work.<br><a href="https://www.ilfattoquotidiano.it/2015/04/29/moda-laltra-faccia-della-cambogia-produrre-in-modo-etico-si-puo-la-storia-del-24enne-aaron-jones/1628362/" target="_blank" rel="noopener">Fikay’s Cambodia story · 2015 archive ↗</a></p></div>`},
 {id:'discovery',name:'A new way to discover',theme:'dark',html:copy('Visual search / SeeFashion','What if the image<br>was the question?','Twelve years ago, I was exploring visual search. With SeeFashion, I built around computer vision and discovery: helping people find what they meant, even when they didn’t have the words.',detail('seefashion','Visual search and discovery'))+`<div class="discovery-art layer" data-direction="top"><span class="diagram-label">The shift in interaction</span><div class="search-question"><span>Describe what you’re looking for…</span><strong>Show me.</strong></div><div class="discovery-flow"><span>Image</span><i>→</i><span>Understanding</span><i>→</i><span>Discovery</span></div><p>From searching with words<br>to searching with what we see.</p><span class="diagram-note">A concept diagram, not a product screenshot</span></div>`},
 {id:'generated-video',name:'A new way to communicate',theme:'dark',html:copy('Generative video / Yepic AI','Zero-shot talking photos.<br>A new way to make video.','At Yepic, we turned a single photo into a talking face—without training a new model for every person. I brought research, engineering and product together to make this available commercially, beginning in 2020.',detail('video-foundations','The early generative video work'))+`<div class="video-era layer" data-direction="right"><div class="source-to-video">${image('assets/optimised/yepic-studio-interface.webp','Yepic Studio: a talking-photo video in the editor, from the Product Hunt gallery','studio-evidence')}<span class="era-equation">From a single photo<br>to a shareable video.</span></div><div class="era-proof"><strong>1 million+</strong><span>Yepic Studio videos generated<br>Documented by OVHcloud, 2022</span></div></div>`},
 {id:'connections',name:'From video to a conversation',theme:'light',html:copy('Live AI / Conversations, not just clips','Not just a face.<br>Someone to talk to.','We gave people a way to talk with an AI persona: to confess a marketing sin, explore a conference or practise their first interview. My work joined the models, the interface and the live experience.',detail('rory','Rory at MADFest')+detail('live-hosts','London Tech Week')+detail('international','AI interview coach'))+`<div class="live-composition layer" data-direction="right">${film('rory','AI Rory')}<button class="supporting-frame depth-layer" data-depth=".45" data-project="live-hosts">${image(photo('live-hosts'),'London Tech Week AI hosts')}<span>London Tech Week · Live knowledge</span></button></div>`},
 {id:'cinema-breakthrough',name:'A new way to make cinema',theme:'dark',kind:'wide-film',html:`<div class="wide-film-heading layer" data-direction="top"><p class="eyebrow">Big Screen Hack / Cannes</p><h2>Making room for<br><em>new forms of AI cinema.</em></h2><p>Big Screen Hack gives filmmakers and AI engineers the tools, collaborators and space to try something they couldn’t make alone. Forty-eight hours to experiment, finish a film and put it in front of a real cinema audience. I bring the people, partners and screenings together—so an idea gets the chance to become an art form.</p></div>${film('creative-community','lilies')}<div class="film-attribution">Film: <strong>lilies</strong> · Muja Studios / Jabir Mohammed<br>My role: organising the people, partners and experience.<br><span>Independent screening at Cinéum Cannes · May 2026</span></div>`},
 {id:'together',name:'The teams that make it happen',theme:'light',html:copy('Good Omen / Two hackathon wins','New approaches to AI video.<br>Two winning teams.','With Giovanni Funchal and Marko Stapfner, I won the AI Engine Summer Hack and Project Europe × Lovable. In Stockholm we built two products in under twenty hours. Impact Loop acquired the journalist tool.',detail('good-omen','The Stockholm win')+detail('ai-engine','The Summer Hack win'))+`<div class="winning-composition layer" data-direction="right">${image('assets/good-omen-stockholm.jpg','Good Omen celebrating with Impact Loop. Photograph: Jesper Andersson.','winning-main')}<figure class="winning-detail depth-layer" data-depth=".5">${image('assets/good-omen-summer.jpeg','Good Omen presenting at Summer Hack. Photograph: Adam Isfendiyar.')}<figcaption>AI Engine Summer Hack · Overall winners</figcaption></figure></div>`},
 {id:'frontier',name:'The next frontier',theme:'dark',html:copy('Now / World models + StoryMachine','What if the world<br>could respond<br>as you imagine it?','My work is moving from generating clips to real-time, interactive worlds. With StoryMachine, I’m bringing research, planning and creative exploration together—so a team can shape an idea while it is still taking form.',detail('world-models','World models and real-time video')+detail('storymachine','Why I’m building StoryMachine')+detail('open-source','Research and open source'))+`<div class="frontier-visuals layer" data-direction="bottom"><figure>${image('assets/optimised/storymachine-direction.webp','After Hours: a visual direction from StoryMachine')}<figcaption>One idea. Many possible films.</figcaption></figure><figure class="depth-layer" data-depth=".35">${image('assets/optimised/storymachine-casting.webp','StoryMachine’s Mara character reference: front, side and back')}<figcaption>Research. Cast. Direct. Keep the creative intent together.</figcaption></figure><a class="story-link" href="https://www.storymachine.ai/" target="_blank" rel="noopener">From the StoryMachine creative studio ↗</a></div>`},
 {id:'build-with-you',name:'Your next breakthrough',theme:'light',html:copy('Strategy + engineering + delivery','The next difficult<br>problem could<br>be yours.','I work with clients from the first conversation through to the build. Sometimes that means a private AI system on local hardware. Sometimes it means helping a leadership team decide where to start—and giving their people the skills to do it.',detail('research','On-premise AI · Oracle + Abu Dhabi Aviation')+detail('oman','AI video at national scale · Oman')+detail('ai-consulting','Consulting and team training'))+`<div class="client-path layer" data-direction="right"><p>How I work with you</p><ol><li><span>Listen</span><strong>What are you trying to change?</strong></li><li><span>Find the possibility</span><strong>What can the technology do now?</strong></li><li><span>Build it together</span><strong>What will make it work in your world?</strong></li></ol><a class="primary-action" href="https://calendar.app.google/pZkjBD1BnG83RQxi7" data-booking>Tell me about the project</a></div>`},
 {id:'contact',name:'Let’s talk',theme:'dark',html:copy('Build with me / Bring me to your stage','Let’s make<br>something<br>happen.','A research challenge, a product, a room full of people ready to explore what comes next. Tell me what you have in mind.',`<a class="primary-action" href="https://calendar.app.google/pZkjBD1BnG83RQxi7" data-booking>Arrange a call</a><a class="story-link" href="mailto:aaronjonesvideo@gmail.com?subject=Speaking%20enquiry">Book me to speak</a><a class="story-link" href="mailto:aaronjonesvideo@gmail.com?subject=Role%20opportunity">Talk about a role</a>`)+`<div class="speaker-gallery layer" data-direction="right"><figure>${image('assets/saudi-speaking.jpeg','Aaron Jones speaking at DeepFest and LEAP in Saudi Arabia')}<figcaption>Expert on generative media · DeepFest / LEAP</figcaption></figure><figure>${image('assets/optimised/aws-summit.webp','Aaron on the generative AI panel at AWS Summit London, April 2024')}<figcaption>AWS Summit London · Generative AI panel</figcaption></figure></div>`}
 ];

 const clientNames=['Chicago Transit Authority','Acronis','Concentrix','Roche','LEAP','GAIN','COMEX','Deriv','Lumen5','GymNation','XRSpace','Seniorly'];
 chapters.splice(4,0,{id:'clients',name:'Trusted to deliver',theme:'dark',html:copy('Founder. CEO. Project leader.','Trusted by international<br>brands and government.','I founded and led Yepic, taking it from early video research to a platform used by more than 100,000 people. I led these projects from the first client conversation through to delivery—bringing the research, engineering and creative teams together to make them happen.',detail('research','Enterprise delivery')+detail('live-hosts','Live experiences'))+'<div class="client-proof layer" data-direction="right"><p class="client-total">100,000+</p><p>People using the platform I founded and led.</p><div class="client-logo-grid">'+clientNames.map((name,i)=>'<figure>'+image('assets/optimised/yepic-client-'+i+'.webp',name)+'</figure>').join('')+'</div></div>'});
 const honours=[
 ['Honours and personal recognition',[
 ['British Empire Medal','2016 · Services to ethical fashion'],
 ['Ernst & Young Future 50','2013'],['Young Entrepreneur of the Year','Camden'],
 ['University of Essex Alumnus of the Year','2018'],['Shell LiveWIRE',''],['Virgin Pioneers',''],
 ['Forbes 30 Under 30','Nominee · 2018']]],
 ['Entrepreneurship and company recognition',[
 ['Great British Entrepreneur Awards','Winner and subsequent finalist recognition'],
 ['Publicis 90',''],['VivaTech · Thrive in SF','Pitch competition winner'],['Intuit Top 100',''],
 ['International Social Enterprise of the Year','Silver award · Fikay'],
 ['Guardian Small Business Awards','Fikay'],['FUTR RetailTech Top 50','2018 · SeeFashion'],
 ['Scale Up of the Year','2021']]],
 ['Hackathons and milestones',[
 ['Project Europe × Lovable / 20VC','2025 · Good Omen · Winner; journalist tool acquired by Impact Loop'],
 ['AI Engine Summer Hack','2025 · Good Omen · Overall winner'],
 ['Product Hunt · #2 Product of the Day','2 June 2022 · Yepic’s RoyalAIness launch'],
 ['Commercial zero-shot talking photos','2020 · Yepic AI · Technology milestone'],
 ['Exited founder','Company-building milestone']]]
 ];
 chapters.splice(chapters.length-1,0,{id:'recognition',name:'Recognition across the years',theme:'light',html:copy('About me / Recognition','Different frontiers.<br>A consistent record.','From ethical fashion to computer vision and generative AI, the work has kept changing. The drive hasn’t: get there early, build something worth using, and bring people with you.','<a class="story-link" href="https://www.linkedin.com/in/aaronbenjaminjones/" target="_blank" rel="noopener">My career on LinkedIn ↗</a>')+'<div class="recognition-catalog layer" data-direction="right" tabindex="0" aria-label="Awards, recognition and milestones; scroll to explore">'+honours.map(([label,items])=>'<h3>'+esc(label)+'</h3><ul>'+items.map(([name,note])=>'<li>'+esc(name)+(note?'<small>'+esc(note)+'</small>':'')+'</li>').join('')+'</ul>').join('')+'<a class="source-link" href="https://www.essex.ac.uk/alumni/awards/alumnus-of-the-year/2018" target="_blank" rel="noopener">University of Essex recognition ↗</a></div>'});
 for(const c of chapters){const section=document.createElement('section');section.id=c.id;section.className='film-scene '+(c.kind||'');section.dataset.title=c.name;section.dataset.theme=c.theme;section.setAttribute('aria-label',c.name);section.innerHTML=c.html.replaceAll('<br>','<br> ');stage.append(section)}
 window.PortfolioNarrative={chapters,record,esc};
})();
